begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.ml(t text) returns uuid language sql immutable as $$select md5('learning-tests-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.ml(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.ml(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-learning@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.ml('org'),'Aprendizado fictício','learning-test-org','active'),(pg_temp.ml('other'),'Outro ministério','learning-test-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.ml('a'),pg_temp.ml('org'),'Igreja A','a','headquarters'),(pg_temp.ml('b'),pg_temp.ml('org'),'Igreja B','b','campus'),(pg_temp.ml('c'),pg_temp.ml('other'),'Igreja externa','c','headquarters');
insert into public.organization_memberships(organization_id,user_id,default_unit_id,role,status) select pg_temp.ml('org'),pg_temp.ml(t),pg_temp.ml('a'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second','unconfirmed'])t;
insert into private.learning_programs(id,organization_id,unit_id,kind,title,steps,created_by,nonce) values
(pg_temp.ml('journey'),pg_temp.ml('org'),pg_temp.ml('a'),'journey','Jornada fictícia','[{"title":"Primeira etapa","body":"Reflexão fictícia","href":"","readings":[{"book":"GEN","chapter":1}]},{"title":"Segunda etapa","body":"Reflexão fictícia","href":"","readings":[{"book":"GEN","chapter":2}]}]',pg_temp.ml('owner'),'journey-test-nonce'),
(pg_temp.ml('reading'),pg_temp.ml('org'),pg_temp.ml('a'),'reading','Plano fictício','[{"title":"Dia um","body":"Leia","href":"","readings":[{"book":"JHN","chapter":1}]},{"title":"Dia dois","body":"Leia","href":"","readings":[{"book":"JHN","chapter":2}]}]',pg_temp.ml('owner'),'reading-test-nonce'),
(pg_temp.ml('draftb'),pg_temp.ml('org'),pg_temp.ml('b'),'journey','Rascunho igreja B','[{"title":"Etapa um","body":"Reservado","href":"","readings":[]}]',pg_temp.ml('owner'),'other-test-nonce');
create function pg_temp.self(a text,id uuid default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.member_learning_self(pg_temp.ml('org'),pg_temp.ml('a'),a,id,v,d)$$;
create function pg_temp.admin(a text,id uuid default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.member_learning_admin(pg_temp.ml('org'),pg_temp.ml('a'),a,id,v,d)$$;
create function pg_temp.enrollment(t text,p text) returns uuid language sql security definer as $$select id from private.learning_enrollments where user_id=pg_temp.ml(t) and program_id=pg_temp.ml(p)$$;
select is((select count(*)::integer from private.scripture_books),66,'66 livros na referência canônica');
select is((select sum(cardinality(verses))::integer from private.scripture_books),1189,'1189 capítulos');
select ok(private.scripture_valid('{"book":"PSA","chapter":119,"verse":176}'),'último versículo do Salmo 119 válido');
select ok(not private.scripture_valid('{"book":"PSA","chapter":119,"verse":177}'),'versículo inexistente recusado');
select ok(not private.learning_steps_valid('reading','[{"title":"Dia um","body":"","href":"","readings":[]}]'),'plano exige capítulo em cada etapa');
select ok(not private.learning_steps_valid('journey','[{"title":"Etapa","body":"","href":"javascript:alert(1)","readings":[]}]'),'link inseguro recusado');
select ok(not has_table_privilege('authenticated','private.scripture_preferences','select'),'preferências sem leitura direta');
select ok(not has_table_privilege('anon','private.learning_enrollments','select'),'progresso privado');
select pg_temp.actor('unconfirmed');set local role authenticated;
select throws_ok($$select pg_temp.self('mine')$$,'42501',null,'email não confirmado não grava progresso');
reset role;select pg_temp.actor('outside');set local role authenticated;
select throws_ok($$select pg_temp.self('reader')$$,'42501','community_denied','outra organização não lê posição');
reset role;select pg_temp.actor('member');set local role authenticated;
select throws_ok($$select pg_temp.admin('list')$$,'42501','learning_denied','membro não administra conteúdo');
select throws_ok($$select pg_temp.self('enroll',pg_temp.ml('journey'))$$,'40001','learning_closed','rascunho não recebe inscrições');
reset role;select pg_temp.actor('owner');set local role authenticated;
select lives_ok($$select pg_temp.admin('publish',pg_temp.ml('journey'),1)$$,'publicar jornada revisada');
select lives_ok($$select pg_temp.admin('publish',pg_temp.ml('reading'),1)$$,'publicar plano de leitura');
select throws_ok($$select pg_temp.admin('reader')$$,'22023','invalid_learning','admin não possui endpoint de preferências');
select throws_ok($$select pg_temp.admin('bookmarks')$$,'22023','invalid_learning','admin não possui endpoint de marcadores');
select throws_ok($$select pg_temp.admin('edit',pg_temp.ml('journey'),2,'{"kind":"journey","title":"Mudança","summary":"","steps":[{"title":"Etapa alterada","body":"","href":"","readings":[]}]}')$$,'40001','learning_immutable','publicação não altera etapas em andamento');
select lives_ok($$select pg_temp.admin('duplicate',pg_temp.ml('journey'),2,'{"nonce":"duplicate-new-edition"}')$$,'nova edição é rascunho separado');
reset role;set local role anon;
select is(jsonb_array_length(public.member_learning_public(pg_temp.ml('org'),pg_temp.ml('a'),'journey')->'items'),1,'visitante vê somente jornada publicada');
select is(public.member_learning_public(pg_temp.ml('org'),pg_temp.ml('b'),'journey',pg_temp.ml('draftb'))->'program','null'::jsonb,'rascunho não expõe etapas');
select is(jsonb_array_length(public.member_learning_public(pg_temp.ml('org'),pg_temp.ml('c'),'journey')->'items'),0,'igreja externa não atravessa organização');
select ok(not(public.member_learning_public(pg_temp.ml('org'),pg_temp.ml('a'),'journey')->'items'->0 ? 'done'),'catálogo público sem progresso pessoal');
reset role;select pg_temp.actor('member');set local role authenticated;
select lives_ok($$select pg_temp.self('enroll',pg_temp.ml('journey'))$$,'inscrição pessoal');
select lives_ok($$select pg_temp.self('enroll',pg_temp.ml('journey'))$$,'repetição da inscrição sem duplicar');
select is(jsonb_array_length(pg_temp.self('mine')->'items'),1,'um progresso por conta e edição');
select throws_ok($$select pg_temp.self('progress',pg_temp.enrollment('member','journey'),1,'{"position":2,"done":true}')$$,'40001','learning_sequence','jornada não pula etapas');
select lives_ok($$select pg_temp.self('progress',pg_temp.enrollment('member','journey'),1,'{"position":1,"done":true}')$$,'concluir etapa um');
select throws_ok($$select pg_temp.self('progress',pg_temp.enrollment('member','journey'),1,'{"position":2,"done":true}')$$,'40001','learning_changed','versão antiga não sobrescreve progresso');
select lives_ok($$select pg_temp.self('progress',pg_temp.enrollment('member','journey'),2,'{"position":2,"done":true}')$$,'concluir jornada');
select ok(pg_temp.self('detail',pg_temp.ml('journey'))->'enrollment'->>'completed_at' is not null,'conclusão registrada');
select ok(exists(select 1 from jsonb_array_elements(public.member_agenda_self(pg_temp.ml('org'),'inbox',pg_temp.ml('a'))->'items')n where n->>'target'='learning'),'conclusão na caixa privada');
select lives_ok($$select pg_temp.self('progress',pg_temp.enrollment('member','journey'),3,'{"position":1,"done":false}')$$,'desmarcar etapa inicial');
select is(jsonb_array_length(pg_temp.self('detail',pg_temp.ml('journey'))->'enrollment'->'done'),0,'desmarcar início limpa etapas seguintes da jornada');
select lives_ok($$select pg_temp.self('enroll',pg_temp.ml('reading'))$$,'iniciar plano');
select lives_ok($$select pg_temp.self('progress',pg_temp.enrollment('member','reading'),1,'{"position":2,"done":true}')$$,'plano permite registrar dia já lido fora de ordem');
select is(pg_temp.self('reader')->'preferences'->>'version','0','preferências iniciais próprias');
select lives_ok($$select pg_temp.self('reader.save',null,0,'{"book":"JHN","chapter":3,"verse":16,"font":22,"theme":"dark"}')$$,'salvar ponto e tema');
select is(pg_temp.self('reader')->'preferences'->>'book','JHN','ponto de leitura recuperado');
select is(pg_temp.self('reader')->'preferences'->>'font','22','fonte sincronizada');
select throws_ok($$select pg_temp.self('reader.save',null,0,'{"book":"GEN","chapter":1,"verse":1,"font":18,"theme":"light"}')$$,'40001','learning_changed','preferência antiga recusada');
select throws_ok($$select pg_temp.self('reader.save',null,1,'{"book":"GEN","chapter":51,"verse":1,"font":18,"theme":"light"}')$$,'22023','invalid_learning','capítulo inexistente recusado');
select lives_ok($$select pg_temp.self('bookmark.add',null,null,'{"book":"JHN","chapter":3,"verse":16}')$$,'marcar versículo');
select lives_ok($$select pg_temp.self('bookmark.add',null,null,'{"book":"JHN","chapter":3,"verse":16}')$$,'marcador repetido não duplica');
select is(jsonb_array_length(pg_temp.self('bookmarks')->'items'),1,'um marcador');
select is(jsonb_array_length(pg_temp.self('marks',null,null,'{"book":"JHN","chapter":3}')->'items'),1,'marcador recuperado no capítulo');
select lives_ok($$select public.member_community_self(pg_temp.ml('org'),null,'note.create',null,null,'{"nonce":"bible-note-integration","title":"João 3:16 — BLIVRE","body":"Reflexão fictícia com referência e atribuição."}')$$,'anotação bíblica usa as anotações privadas existentes');
reset role;select pg_temp.actor('second');set local role authenticated;
select is(jsonb_array_length(pg_temp.self('mine')->'items'),0,'outra conta não vê progresso');
select is(pg_temp.self('detail',pg_temp.ml('journey'))->'enrollment','null'::jsonb,'outra conta não lê inscrição pelo ID');
select throws_ok($$select pg_temp.self('progress',pg_temp.enrollment('member','journey'),4,'{"position":1,"done":true}')$$,'42501','learning_denied','outra conta não edita progresso');
select is(jsonb_array_length(pg_temp.self('bookmarks')->'items'),0,'outra conta não vê marcadores');
select is(pg_temp.self('reader')->'preferences'->>'version','0','outra conta não vê preferências salvas');
reset role;select pg_temp.actor('owner');set local role authenticated;
select lives_ok($$select pg_temp.admin('archive',pg_temp.ml('journey'),2)$$,'arquivar para novas inscrições');
reset role;set local role anon;
select is(jsonb_array_length(public.member_learning_public(pg_temp.ml('org'),pg_temp.ml('a'),'journey')->'items'),0,'arquivado sai do catálogo público');
reset role;select pg_temp.actor('second');set local role authenticated;
select throws_ok($$select pg_temp.self('enroll',pg_temp.ml('journey'))$$,'40001','learning_closed','arquivado não recebe novos inscritos');
reset role;select pg_temp.actor('member');set local role authenticated;
select is(pg_temp.self('detail',pg_temp.ml('journey'))->'program'->>'status','archived','inscrito conserva edição arquivada');
select lives_ok($$select pg_temp.self('progress',pg_temp.enrollment('member','journey'),4,'{"position":1,"done":true}')$$,'inscrito pode continuar edição arquivada');
select lives_ok($$select pg_temp.self('bookmark.remove',null,null,'{"book":"JHN","chapter":3,"verse":16}')$$,'remover marcador próprio');
select is(jsonb_array_length(pg_temp.self('bookmarks')->'items'),0,'marcador removido');
reset role;
select is((select role::text from public.organization_memberships where user_id=pg_temp.ml('member') and organization_id=pg_temp.ml('org')),'member','conclusão não concede cargo');
select ok(not exists(select 1 from public.audit_logs where organization_id=pg_temp.ml('org') and metadata::text like '%JHN%'),'auditoria não expõe hábitos individuais de leitura');
select * from finish();rollback;
